        clauses.append("INSTR(title, ?) > 0")
        params.append(query)
    counts = dict.fromkeys(VALID_STATUSES, 0)
    try:
        require_project(conn, project_id)
        rows = conn.execute(
            "SELECT status, COUNT(*) FROM tasks WHERE "
